 // \"not asked yet\", distinct from a learner explicitly choosing every day.\n  weeklyGoalDays    Int?\n  /**\n   * Reminder email settings. Off unless the learner turns them on — a streak is a memory\n   * aid, not a threat (LEARNER-LIFECYCLE.md §1.2), and an unasked-for daily email is the\n   * fastest way to turn one into the other.\n   * `reminderHour` is an hour in the learner's own `timezone`, which is why the cron runs\n   * hourly and each user's local time is computed rather than stored: one UTC send time\n   * would reach Bangkok and Berlin at unrelated moments of their day.\n   * `lastReminderOn` is a local date string (`YYYY-MM-DD`), and it is the idempotency\n   * key. D1 has no transactions, so \"did we already mail this person today\" cannot be a\n   * read-modify-write on a timestamp — it is a compare against a date the send itself\n   * writes.\n   */\n  /**\n   * /**\n   * The list this learner is studying. Defaults to the Oxford 3000 course, which is what\n   * every existing learner is on, so the column is inert until a second list is\n   * published.\n   */\n  wordlistId        String             @default(\"oxford-3000\")\n  reminderOptIn     Boolean            @default(false)\n  reminderHour      Int?\n  lastReminderOn    String?\n  lastRecapOn       String?\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n  learningSessions  LearningSession[]\n  quizResults       QuizResult[]\n  unitProgresses    UserUnitProgress[]\n  wordProgresses    UserWordProgress[]\n  wordAttempts      UserWordAttempt[]\n  magicLinkTokens   MagicLinkToken[]\n  mixedSessions     MixedSession[]\n  completions       CompletionLedger[]\n  unitCheckpoints   UnitCheckpoint[]\n  pushSubscriptions PushSubscription[]\n\n  // The hourly reminder cron reads only opted-in learners; without this it scans every\n  // account once an hour forever.\n  @@index([reminderOptIn])\n}\n\n/**\n * A browser's push endpoint, so a reminder can reach an installed PWA without an inbox.\n * One row per browser, not per learner: the same account on a phone and a laptop is two\n * subscriptions, and revoking one must not silence the other. `endpoint` is unique because\n * it *is* the identity — the push service issues it, and re-subscribing the same browser\n * returns the same value.\n * `p256dh` and `auth` are the client keys for encrypted payloads. Nothing sends a payload\n * today (see `src/push.ts`: the notification text is fetched by the service worker, which\n * avoids implementing aes128gcm on a Worker), and they are stored because a subscription\n * cannot be re-keyed later — the browser hands them over once, at subscribe time.\n */\nmodel PushSubscription {\n  id        String    @id @default(cuid())\n  userId    String\n  endpoint  String    @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime  @default(now())\n  // Set when a push service answers 404/410: the subscription is gone for good, and the\n  // row is kept only long enough for the next pass to skip it and delete it.\n  failedAt  DateTime?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n}\n\nmodel MagicLinkToken {\n  id        String    @id @default(cuid())\n  tokenHash String    @unique\n  userId    String\n  expiresAt DateTime\n  usedAt    DateTime?\n  createdAt DateTime  @default(now())\n  user      User      @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // The PracticeTrial id owned by *this browser* at the moment it called\n  // `requestMagicLink` — the trial claim cookie is verified right there and only the bare\n  // id is kept, never the signed bearer token itself (LEARNER-LIFECYCLE.md §3.3).\n  // Verifying the link in a different cookie jar (LINE's in-app browser handing off to\n  // the system browser) recovers the trial from this column alone — no bearer trial\n  // claim ever rides in the URL, a referrer header, or browser hi